     1	import React from 'react';
     2	import { Text } from '@chakra-ui/react';
     3	
     4	type ZimmProductNameProps = {
     5	  /** The product's display name, already resolved by the caller. */
     6	  name: string;
     7	  /**
     8	   * Heading level. Required rather than defaulted: the correct level depends on what else the
     9	   * page has already emitted, and a silent `h1` default duplicates the base PDP's own
    10	   * screen-reader-only `<h1>Product Details</h1>`.
    11	   */
    12	  as: 'h1' | 'h2' | 'h3';
    13	};
    14	
    15	/**
    16	 * Atom — the product name. No recipe: the whole spec is one `textStyle` plus a semantic colour
    17	 * token, which tiers 1-2 of .claude/rules/overrideStyling.md already cover.
    18	 */
    19	export const ZimmProductName = ({ name, as }: ZimmProductNameProps) => (
    20	  <Text as={as} textStyle="heading3" color="text.default" data-testid="product-name">
    21	    {name}
    22	  </Text>
    23	);
