     1	import React from 'react';
     2	import { Text } from '@chakra-ui/react';
     3	import { isBlankRichText, parseRichText } from 'app/utils/richText';
     4	
     5	type ZimmProductModelInfoProps = {
     6	  /**
     7	   * Model copy from the product's `c_modelFit` attribute. Business Manager authors this as
     8	   * rich text, so it is parsed rather than rendered as a raw string.
     9	   */
    10	  modelInfo?: string;
    11	};
    12	
    13	/**
    14	 * Atom — the model line ("Model is 178cm and wears a size 0"). Renders nothing when
    15	 * `c_modelFit` is absent, which is the common case today. No recipe: one `textStyle` plus a
    16	 * semantic colour token.
    17	 */
    18	export const ZimmProductModelInfo = ({ modelInfo }: ZimmProductModelInfoProps) => {
    19	  if (isBlankRichText(modelInfo)) return null;
    20	  const content = parseRichText(modelInfo);
    21	
    22	  return (
    23	    <Text as="div" textStyle="caption" color="text.default" data-testid="product-model-info">
    24	      {content}
    25	    </Text>
    26	  );
    27	};

