 86	  while (i < line.length) {
 87	    if (state.inBlockComment) {
 88	      const end = line.indexOf('*/', i);
 89	      if (end === -1) return result;
 90	      i = end + 2;
 91	      state.inBlockComment = false;
 92	      continue;
 93	    }
